"""Generated byte-binding regressions; no authentic movies or manual targets."""
from __future__ import annotations

import hashlib
import importlib.util
import io
import json
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

import numpy as np


MODULE = Path(__file__).resolve().parents[1] / "source_panel.py"
SPEC = importlib.util.spec_from_file_location("snapshot_panel_under_test", MODULE)
PANEL = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(PANEL)


def digest(body):
    return hashlib.sha256(body).hexdigest()


def npy_bytes(array):
    stream = io.BytesIO()
    np.save(stream, array, allow_pickle=False)
    return stream.getvalue()


class MaskSnapshotTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.path = self.root / "masks.npy"
        self.manifest = self.root / "manifest.json"
        self.original = np.array([[[1, 0, 0], [0, 0, 0]]], dtype=bool)
        self.changed = np.array([[[0, 0, 0], [0, 0, 1]]], dtype=bool)
        self.body = npy_bytes(self.original)
        self.path.write_bytes(self.body)
        self.row = {"mask_file": self.path.name, "mask_sha256": digest(self.body)}
        self.shape_patch = patch.object(PANEL, "IMAGE_SHAPE", (2, 3))
        self.shape_patch.start()
        self.addCleanup(self.shape_patch.stop)

    def test_replacement_between_authentication_and_decode_uses_captured_bytes(self):
        original_load = np.load

        def replace_then_load(source, *args, **kwargs):
            replacement = self.root / "replacement.npy"
            replacement.write_bytes(npy_bytes(self.changed))
            replacement.replace(self.path)
            return original_load(source, *args, **kwargs)

        with patch.object(PANEL.np, "load", side_effect=replace_then_load):
            masks = PANEL._load_masks(self.row, self.manifest)
        np.testing.assert_array_equal(masks, self.original)
        np.testing.assert_array_equal(original_load(self.path), self.changed)

    def test_in_place_mutation_after_load_cannot_change_scored_array(self):
        masks = PANEL._load_masks(self.row, self.manifest)
        self.path.write_bytes(npy_bytes(self.changed))
        np.testing.assert_array_equal(masks, self.original)
        self.assertNotIsInstance(masks, np.memmap)

    def test_changed_input_is_rejected_before_numpy_decoding(self):
        self.path.write_bytes(npy_bytes(self.changed))
        with patch.object(PANEL.np, "load") as load:
            with self.assertRaisesRegex(ValueError, "SHA256 mismatch"):
                PANEL._load_masks(self.row, self.manifest)
        load.assert_not_called()

    def test_npz_is_not_accepted_as_standalone_npy(self):
        stream = io.BytesIO()
        np.savez(stream, masks=self.original)
        body = stream.getvalue()
        self.path.write_bytes(body)
        self.row["mask_sha256"] = digest(body)
        with self.assertRaisesRegex(ValueError, "standalone NPY"):
            PANEL._load_masks(self.row, self.manifest)

    def test_object_array_is_rejected_without_pickle_loading(self):
        stream = io.BytesIO()
        np.save(stream, np.array([{"not": "a mask"}], dtype=object), allow_pickle=True)
        body = stream.getvalue()
        self.path.write_bytes(body)
        self.row["mask_sha256"] = digest(body)
        with self.assertRaisesRegex(ValueError, "allow_pickle=False"):
            PANEL._load_masks(self.row, self.manifest)

    def test_invalid_binary_values_and_full_field_are_still_rejected(self):
        for array, error in ((np.full((1, 2, 3), 0.25), "binary"),
                             (np.ones((1, 3, 2)), "488x488")):
            with self.subTest(shape=array.shape):
                body = npy_bytes(array)
                self.path.write_bytes(body)
                self.row["mask_sha256"] = digest(body)
                with self.assertRaisesRegex(ValueError, error):
                    PANEL._load_masks(self.row, self.manifest)


class ManifestSnapshotTests(unittest.TestCase):
    """Exercise all ten rows using invented source pins and a small MAT stub.

    This tests manifest capture and scoring dispatch, not the real MAT parser or
    the 488x488 scientific field. Those existing controls remain separate.
    """

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.source = self.root / "invented-source"
        self.source.mkdir()
        self.reference = self.root / "reference.json"
        self.prediction = self.root / "prediction.json"
        self.masks = np.ones((1, 2, 3), dtype=bool)
        self.mask_body = npy_bytes(self.masks)
        self.pins = {}
        refs, preds = [], []
        for rid, depth in PANEL.RECORDINGS.items():
            body = ("invented source " + rid).encode("ascii")
            source_name = rid + ".mat"
            (self.source / source_name).write_bytes(body)
            self.pins[rid] = {"path": source_name, "bytes": len(body),
                              "git_blob_sha1": PANEL.git_blob_sha1(body),
                              "sha256": digest(body)}
            mask_name = rid + ".npy"
            (self.root / mask_name).write_bytes(self.mask_body)
            row = {"recording_id": rid, "depth_um": depth,
                   "mask_file": mask_name, "mask_sha256": digest(self.mask_body)}
            preds.append(dict(row))
            refs.append({**row, "roi_count": 1, "source_path": source_name,
                         "source_bytes": len(body),
                         "source_git_blob_sha1": PANEL.git_blob_sha1(body),
                         "source_sha256": digest(body)})
        shape = patch.object(PANEL, "IMAGE_SHAPE", (2, 3))
        shape.start()
        self.addCleanup(shape.stop)
        source_pins = patch.object(PANEL, "source_pins", return_value=self.pins)
        source_pins.start()
        self.addCleanup(source_pins.stop)
        decoder = patch.object(PANEL, "decode_mat", side_effect=lambda _: self.masks.copy())
        decoder.start()
        self.addCleanup(decoder.stop)
        reference = {**PANEL._common(PANEL.REFERENCE_SCHEMA), "recordings": refs,
                     "author_revision": PANEL.AUTHOR_REVISION,
                     "conversion": PANEL.CONVERSION}
        self.reference_body = json.dumps(reference).encode("utf-8")
        self.reference.write_bytes(self.reference_body)
        prediction = {**PANEL._common(PANEL.PREDICTION_SCHEMA), "recordings": preds,
                      "policy_id": PANEL.POLICY_ID,
                      "method_id": "generated-original",
                      "implementation_identity": "generated control; no model",
                      "reference_manifest_sha256": digest(self.reference_body)}
        self.prediction_body = json.dumps(prediction).encode("utf-8")
        self.prediction.write_bytes(self.prediction_body)

    def test_manifests_replaced_after_capture_keep_original_content_and_digests(self):
        original_read = Path.read_bytes
        captures = {self.reference: 0, self.prediction: 0}

        def replace_after_capture(path):
            body = original_read(path)
            if path in captures:
                captures[path] += 1
                if captures[path] == 1:
                    changed = json.loads(body)
                    changed["method_id"] = "different-later-content"
                    path.write_text(json.dumps(changed))
            return body

        with patch.object(Path, "read_bytes", replace_after_capture):
            result = PANEL.score_panel(self.reference, self.prediction, self.source)
        self.assertEqual(result["method_id"], "generated-original")
        self.assertEqual(result["reference_manifest_sha256"], digest(self.reference_body))
        self.assertEqual(result["prediction_manifest_sha256"], digest(self.prediction_body))
        self.assertEqual(result["summary"]["video_count"], 10)
        self.assertEqual(result["summary"]["f1"]["macro_video_mean"], 1.0)
        self.assertEqual(captures, {self.reference: 1, self.prediction: 1})
        self.assertNotEqual(digest(self.reference.read_bytes()), digest(self.reference_body))
        self.assertNotEqual(digest(self.prediction.read_bytes()), digest(self.prediction_body))

    def test_prediction_reference_binding_uses_captured_reference_digest(self):
        prediction = json.loads(self.prediction_body)
        prediction["reference_manifest_sha256"] = "0" * 64
        self.prediction.write_text(json.dumps(prediction))
        with self.assertRaisesRegex(ValueError, "another reference"):
            PANEL.score_panel(self.reference, self.prediction, self.source)

    def test_duplicate_manifest_keys_remain_rejected(self):
        self.prediction.write_text('{"method_id":"first", "method_id":"second"}')
        with self.assertRaisesRegex(ValueError, "duplicate JSON key"):
            PANEL.score_panel(self.reference, self.prediction, self.source)


if __name__ == "__main__":
    unittest.main()
